COMMON_JS = r'''
// 所有互動只改變這份設計稿，不存檔、不呼叫裝置或網路。
const $ = s => document.querySelector(s);
$('#theme').onclick = () => { const dark = document.documentElement.dataset.theme !== 'dark'; document.documentElement.dataset.theme = dark ? 'dark' : 'light'; $('#theme').textContent = dark ? '☀ 日間' : '☾ 夜間'; $('#theme').setAttribute('aria-pressed', String(dark)); };
let toastTimer;
function toast(text){$('#toast').textContent=text; clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').textContent='',3500)}
document.querySelectorAll('[data-message]').forEach(b=>b.onclick=()=>toast(b.dataset.message));
document.querySelectorAll('[data-dialog]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.dialog).showModal());
document.querySelectorAll('dialog [data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
'''

def shell(page, title, subtitle, content, heading='', script='', dialogs=''):
    nav = [('dashboard','即時監測'),('actions','動作處方'),('history-review','療程紀錄'),('settings','設定')]
    links = ''.join(f'<a href="mockup-{key}.html" class="{"active" if key == page else ""}" {"aria-current=page" if key == page else ""}>{name}</a>' if key != 'actions' else '<button data-dialog="actions-dialog">動作處方</button>' for key,name in nav)
    action_dialog = '''<dialog id="actions-dialog"><h2>動作處方 · 版面預覽</h2><p class="muted">完整配置見 PROPOSAL.md。每個動作分成名稱列與固定參數列，長標籤不擠壓按鈕。</p><div class="setting-row"><div><h3>直膝後擺</h3><p>大腿後伸 ≥20° · 保持 2 秒 · 超限 30°</p></div><span class="pill">肢段後伸</span></div><div class="setting-row"><div><h3>坐姿屈膝</h3><p>膝角 80–100° · 保持 3 秒 · 超限 135°</p></div><span class="pill">關節角度</span></div><div class="setting-row"><div><h3>直膝抬腿</h3><p>大腿仰角 ≥45° · 保持 3 秒 · 超限 80°</p></div><span class="pill">肢段抬高</span></div><div class="row"><button data-close>返回</button></div></dialog>'''
    return f'''<!doctype html><html lang="zh-Hant" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · IRMS 復健工作簿</title><style>{CSS}</style></head><body><div class="app"><header class="top"><a class="brand" href="mockup-dashboard.html" aria-label="IRMS 即時監測"><span class="brand-mark">∿</span><span class="brand-word">IRMS</span></a><nav class="navigation" aria-label="主導覽">{links}</nav><div class="top-right"><span class="connection">○ 設計預覽 · 離線</span><button id="theme" class="small quiet" aria-pressed="false" aria-label="切換日間與夜間主題">☾ 夜間</button></div></header><main class="page"><header class="page-heading"><div><h1>{title}</h1><p>{subtitle}</p></div>{heading}</header>{content}</main><footer class="footer"><span>IRMS / 復健工作簿 · 設計提案 03</span><span>所有數值皆為示意 · 不連線、不儲存、不上傳</span></footer></div><div id="toast" role="status"></div>{action_dialog}{dialogs}<script>{COMMON_JS}{script}</script></body></html>'''

POSE = '''<svg class="pose-svg" id="pose-drawing" viewBox="0 0 440 290" role="img" aria-label="側面示意：大腿水平，小腿向下，屈膝約 86 度；非量測影像"><defs><linearGradient id="limb"><stop stop-color="var(--accent)"/><stop offset="1" stop-color="var(--muted)"/></linearGradient></defs><g class="pose-ground" fill="none" stroke="var(--line)"><ellipse cx="246" cy="259" rx="132" ry="17"/><path d="M50 259H395 M88 79V250H193" stroke-width="2"/><path d="M172 30V258" stroke-dasharray="4 5"/></g><path d="M100 35 L113 90 L249 97" fill="none" stroke="var(--edge)" stroke-width="24" stroke-linecap="round" opacity=".45"/><path d="M118 92 L249 97" fill="none" stroke="url(#limb)" stroke-width="25" stroke-linecap="round"/><path d="M249 97 L258 234 L294 240" fill="none" stroke="var(--accent)" stroke-width="20" stroke-linecap="round" stroke-linejoin="round"/><circle cx="249" cy="97" r="17" fill="var(--paper)" stroke="var(--accent)" stroke-width="4"/><circle cx="249" cy="97" r="5" fill="var(--accent)"/><path d="M198 96 Q201 143 252 148" fill="none" stroke="var(--good)" stroke-width="2"/><path d="M249 97 L330 97" stroke="var(--edge)" stroke-dasharray="4 5"/><text x="173" y="63">大腿</text><text x="289" y="180">小腿</text><text x="192" y="162" style="fill:var(--good);font-size:18px;font-weight:600">86°</text><text x="315" y="35">前方 →</text><text x="53" y="280">側面 / 矢狀面</text></svg>'''

dashboard = f'''<section class="sheet live-sheet" id="live" data-state="holding" aria-label="即時監測示意"><div class="coach" aria-live="polite"><span class="coach-symbol" id="coach-symbol">✓</span><div><h2 id="coach-title">很好，保持這個位置</h2><small id="coach-sub">已進入目標區間，保持滿 3 秒後再回位。</small></div><div class="hold-copy"><strong id="remaining">再保持 1.2 秒</strong><br><small>第 7 次 · 保持中</small></div></div><div class="live-main"><div class="metric"><p class="metric-label">主指標 · 膝關節夾角</p><div class="metric-number num" id="metric-number">86<span class="unit">°</span></div><div class="metric-caption"><span><strong>80–100°</strong> 目標區間</span><span class="muted">超限門檻 135°</span></div><div class="target-meter" aria-label="目前 86 度，目標 80 至 100 度，超限門檻 135 度"><div class="meter"><span class="target"></span><span class="limit"></span><span class="point" id="meter-point"></span></div><div class="meter-labels"><span>0° / 起始</span><span>目標 80–100°</span><span>135° 超限</span><span>160°</span></div></div></div><div class="pose"><div class="section-title"><h3>動作姿態</h3><div class="segment" aria-label="姿態檢視"><button id="pose-2d" aria-pressed="true">2D 側面</button><button id="pose-3d" aria-pressed="false">3D 概念</button></div></div>{POSE}<p class="pose-note" id="pose-note">✓ 已完成校準 · 14:02　／　側向角度未驗證<br>姿態為方向示意；不判讀內外翻。</p></div></div><div class="session-dock"><div><div class="dock-label">已完成</div><div class="dock-value num">6 <span class="muted" style="font-size:15px">次</span></div></div><div><div class="dock-label">本次保持</div><div class="dock-value num" id="hold-value">1.8 <span class="muted" style="font-size:15px">/ 3.0 秒</span></div><div class="hold-track"><span id="hold-fill"></span></div></div><div class="dock-time"><div class="dock-label">療程時間</div><div class="dock-value num">02:18</div></div><div class="row"><button id="alarm-mute" hidden>靜音 30 秒</button><button class="primary" data-dialog="finish-dialog">結束療程</button></div></div></section>'''
dashboard_js = r'''
const stateCopy={holding:['✓','很好，保持這個位置','已進入目標區間，保持滿 3 秒後再回位。','86'],alarm:['!','超出上限，請停止加深','目前 142° · 超限門檻 135° · 警報仍有效。','142'],error:['×','感測器異常 · ERR:1','請停止動作，檢查感測器連接；等待裝置復原。','—'],disconnected:['○','裝置未連線','請先連線裝置；目前沒有即時量測。','—'],uncalibrated:['!','請先完成校準','讀數方向尚未確認；此預覽不提供達標提示。','—']};
$('#state-preview').onchange=e=>{const state=e.target.value,c=stateCopy[state];$('#live').dataset.state=state;$('#coach-symbol').textContent=c[0];$('#coach-title').textContent=c[1];$('#coach-sub').textContent=c[2];$('#metric-number').innerHTML=c[3]+(c[3]==='—'?'':'<span class="unit">°</span>');$('#remaining').textContent=state==='holding'?'再保持 1.2 秒':'請查看狀態提示';$('#hold-value').innerHTML=state==='holding'?'1.8 <span class="muted" style="font-size:15px">/ 3.0 秒</span>':'—';$('#hold-fill').style.width=state==='holding'?'60%':'0';$('#alarm-mute').hidden=state!=='alarm';$('#alarm-mute').textContent='靜音 30 秒';$('#meter-point').style.left=state==='alarm'?'88.75%':'53.75%';$('#pose-drawing').style.visibility=state!=='holding'?'hidden':'visible';$('#calibration-chip').textContent=state==='uncalibrated'?'! 尚未校準':'✓ 校準完成';$('#calibration-chip').className='pill '+(state==='uncalibrated'?'warning':'good');$('#pose-note').textContent=state==='holding'?'✓ 已完成校準 · 14:02 ／ 側向角度未驗證。姿態為方向示意；不判讀內外翻。':state==='alarm'?'超限姿態未在此靜態稿中繪製。正式版保留有效即時姿態。':'無可用姿態；完成連線與校準後顯示。';};
$('#alarm-mute').onclick=()=>{$('#alarm-mute').textContent='靜音中 · 示意';toast('僅預覽靜音狀態；超限警示持續顯示。')};
['2d','3d'].forEach(mode=>$('#pose-'+mode).onclick=()=>{['2d','3d'].forEach(m=>$('#pose-'+m).setAttribute('aria-pressed',String(m===mode)));$('#pose-drawing').style.transform=mode==='3d'?'perspective(700px) rotateY(-22deg)':'none';$('#pose-note').textContent=mode==='3d'?'3D 構圖示意（此處為 SVG，非 three.js）。正式版固定斜側視角；Yaw 不可量測、Roll 未驗證。':'✓ 已完成校準 · 14:02 ／ 側向角度未驗證。姿態為方向示意；不判讀內外翻。';});
'''
heading = '''<div class="row"><span class="pill good" id="calibration-chip">✓ 校準完成</span><label class="eyebrow" for="state-preview">狀態預覽</label><select class="status-select" id="state-preview" aria-label="切換設計稿狀態"><option value="holding">保持中</option><option value="alarm">超限警報</option><option value="error">硬體異常 ERR:1</option><option value="disconnected">未連線</option><option value="uncalibrated">未校準</option></select></div>'''
dialogs = '''<dialog id="finish-dialog"><h2>結束這次療程？</h2><p>坐姿屈膝 · 已完成 6 次 · 02:18</p><p class="muted">這是離線設計稿。正式版會保存本次紀錄，並提供療程回顧。</p><div class="row"><button data-close>返回監測</button><a href="mockup-history-review.html" class="pill" style="background:var(--accent);color:var(--on-accent);padding:12px 16px">查看回顧示意</a></div></dialog>'''
(ROOT/'mockup-dashboard.html').write_text(shell('dashboard','坐姿屈膝','Knee flexion · 目標 90° ±10° · 保持 3 秒',dashboard,heading,dashboard_js,dialogs),encoding='utf-8')

telemetry = '''<section class="settings-pane local-scroll" id="pane-telemetry" aria-label="遙測設定"><div class="eyebrow">資料與隱私 / TELEMETRY</div><h2>協助改善裝置連線</h2><p class="intro">選擇是否將診斷資料傳送給 IRMS 開發團隊。本機量測與療程紀錄不受影響。</p><div class="setting-row"><div><h3>即時遙測上傳</h3><p id="telemetry-status">已關閉 · 沒有資料正在上傳</p></div><label class="switch"><span id="telemetry-label">關閉</span><input id="telemetry-toggle" type="checkbox" aria-label="即時遙測上傳（僅設計稿）"></label></div><div class="disclosure"><div><h3>會傳送什麼</h3><p>原始角度封包、連線與韌體更新狀態、App 日誌，以及療程開始／結束資訊、動作名稱、目標與校準參數。</p></div><div><h3>如何保留</h3><p>伺服器保留 90 天；每次啟動使用新的隨機 ID。不主動蒐集姓名、帳號或電腦名稱；本機紀錄照常保存。</p></div></div><div class="notice">! 動作名稱也會上傳。請勿使用病人或個人姓名命名動作。</div><details id="advanced"><summary>進階連線設定</summary><label class="field">伺服器網址<input id="endpoint" type="url" value="https://hina-tw.ddns.net/irms-api" aria-describedby="endpoint-note"></label><p id="endpoint-note" class="muted" style="font-size:12px;margin-top:6px">上傳開啟時鎖定網址。關閉會捨棄尚未送出的資料。</p></details></section>'''
