settings_js=r'''
document.querySelectorAll('[data-pane]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-pane]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.settings-pane').forEach(p=>p.hidden=p.id!=='pane-'+button.dataset.pane)});
function telemetryState(on){$('#telemetry-toggle').checked=on;$('#telemetry-label').textContent=on?'開啟':'關閉';$('#telemetry-status').textContent=on?'預覽：已上傳 138 筆 · 待傳 32 筆 · 已捨棄 0 筆':'已關閉 · 沒有資料正在上傳';$('#endpoint').disabled=on;$('#settings-save').textContent='僅更新設計稿狀態 · 未儲存或傳送資料'}
$('#telemetry-toggle').onchange=e=>{if(e.target.checked){e.target.checked=false;$('#telemetry-consent').showModal()}else telemetryState(false)};
$('#confirm-telemetry').onclick=()=>{telemetryState(true);$('#telemetry-consent').close()};
'''
