chart=f'''<svg class="chart" viewBox="0 0 735 258" preserveAspectRatio="none" role="img" aria-label="示意療程膝角曲線：9 次嘗試，8 次完成；第 8 次未達標，第 9 次超限至 142 度"><rect x="48" y="98" width="640" height="24" fill="var(--good-bg)"/>{grid}<line class="threshold" x1="48" x2="688" y1="56" y2="56"/><text x="688" y="46" text-anchor="end" style="fill:var(--danger)">135° 超限門檻</text><polyline class="trace" points="{curve}"/><circle cx="630" cy="47.6" r="5" fill="var(--danger)"/><text x="48" y="244">00:00</text><text x="248" y="244">01:30</text><text x="458" y="244">03:00</text><text x="688" y="244" text-anchor="end">04:30</text><text x="12" y="14">°</text></svg>'''
rep_buttons=''.join(f'<button data-rep="{i}" aria-pressed="{str(i==5).lower()}" class="{"rep-warn" if i>=7 else ""}">{i+1:02}<span>{"! 超限" if i==8 else "○ 未達" if i==7 else "✓ 完成"}</span></button>' for i in range(9))
review=f'''<section class="sheet review-sheet"><div class="review-metrics num"><div><small>完成 / 嘗試</small><strong>8 <span>/ 9 次</span></strong></div><div><small>峰值膝角</small><strong>142<span>°</span></strong></div><div><small>平均膝角</small><strong>48.6<span>°</span></strong></div><div><small>目標區時間</small><strong>29<span>%</span></strong></div><div><small>超限事件</small><strong class="danger-text">1 <span>次 · 1.2 秒</span></strong></div><div><small>有效量測</small><strong>4:30</strong></div></div><div class="review-body"><div class="review-chart-area"><div class="section-title"><h3>每一次，都有跡可循</h3><div class="legend"><span><i class="legend-line"></i>膝角</span><span><i class="legend-band"></i>80–100° 目標</span></div></div>{chart}<div class="rep-strip" aria-label="選擇動作嘗試">{rep_buttons}</div><p class="chart-caption">點選一次動作查看峰值與保持時間 · 所有曲線與摘要數值均為設計示例</p></div><aside class="review-aside local-scroll" aria-label="單次動作與比較"><section class="rep-detail"><div class="section-title"><h3 id="rep-title">第 06 次動作</h3><span class="pill good" id="rep-status">✓ 完成</span></div><div class="rep-detail-values num"><div><small>峰值</small><strong id="rep-peak">93°</strong></div><div><small>最長連續保持</small><strong id="rep-hold">3.1 秒</strong></div></div></section><div class="notice"><strong>! 與上次的校準不同</strong><br>零位或鉸鏈軸已變更。以下僅並列，不計算進步幅度。</div><section class="comparison"><h3>同動作 · 上次療程</h3><table><thead><tr><th>坐姿屈膝</th><th>09/23</th><th>本次</th></tr></thead><tbody><tr><td>完成次數</td><td>7</td><td>8</td></tr><tr><td>峰值</td><td>96°</td><td>142°</td></tr><tr><td>保持中位數</td><td>3.0 秒</td><td>3.15 秒</td></tr></tbody></table><p>同處方：90° ±10° / 3 秒<br>校準 A → B · 跨場比較需由治療師確認<br>本次校準亦與目前設定不同</p></section></aside></div></section>'''
review_js='''
const peaks='''+json.dumps(peaks)+''',holds='''+json.dumps(holds)+''';
document.querySelectorAll('[data-rep]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.rep);document.querySelectorAll('[data-rep]').forEach(r=>r.setAttribute('aria-pressed',String(r===b)));$('#rep-title').textContent='第 '+String(i+1).padStart(2,'0')+' 次動作';$('#rep-peak').textContent=peaks[i]+'°';$('#rep-hold').textContent=holds[i].toFixed(1)+' 秒';$('#rep-status').textContent=i===8?'! 完成 / 超限':i===7?'○ 未達標':'✓ 完成';$('#rep-status').className='pill '+(i>=7?'warning':'good');if(innerWidth<=800)toast('第 '+(i+1)+' 次：峰值 '+peaks[i]+'°，保持 '+holds[i].toFixed(1)+' 秒。比較摘要請開啟「比較」。')});
'''
review_heading='''<div class="row"><button class="small" data-dialog="compare-dialog">比較</button><button class="small" data-message="匯出規格見提案：包含原始樣本、處方快照、校準資訊、資料來源與分析版本。此設計稿不產生假療程檔。">匯出紀錄 ↗</button></div>'''
compare_dialog='''<dialog id="compare-dialog"><h2>同動作比較</h2><div class="notice">! 09/23 與 09/25 使用不同校準；不計算進步幅度。本次校準也與目前設定不同。</div><p>坐姿屈膝 · 同處方：90° ±10° / 3 秒</p><p>09/23：完成 7 次、峰值 96°、保持中位數 3.0 秒。</p><p>09/25：完成 8 次、峰值 142°、保持中位數 3.15 秒。</p><p class="muted">較高峰值包含一次超限，不能解讀為進步。正式版另可選擇可比的歷史療程。</p><div class="row"><button data-close>關閉比較</button></div></dialog>'''
(ROOT/'mockup-history-review.html').write_text(shell('history-review','療程回顧','坐姿屈膝 · 2026/09/25 14:30 · 療程 #24 · 示例資料',review,review_heading,review_js,compare_dialog),encoding='utf-8')
print('Wrote three self-contained HTML mockups.')
